public class MutualParityTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("isEven(0)", true, MutualParity.isEven(0));
        check("isOdd(0)", false, MutualParity.isOdd(0));
        check("isEven(1)", false, MutualParity.isEven(1));
        check("isOdd(1)", true, MutualParity.isOdd(1));
        check("isEven(4)", true, MutualParity.isEven(4));
        check("isOdd(7)", true, MutualParity.isOdd(7));
        check("isEven(101)", false, MutualParity.isEven(101));
        check("isOdd(500)", false, MutualParity.isOdd(500));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

